    fs::create_dir_all(&group).unwrap();
    let fake = root.join("fakegit");
    fs::write(
        &fake,
        "#!/bin/sh\n\
         if [ \"$1\" = \"rev-parse\" ]; then exit 1; fi\n\
         printf 'FAKE-GIT-RAN\\n'; exit 0\n",
    )
    .unwrap();
